cypher.cypher:
MATCH (ag:Agent {name: $t.agent})
         CREATE (e:ExecutionTrace {id: $id, agentId: $t.agent, sessionId: $t.run_id, task: $t.task, userQuery: $t.user_query,
                 description: $t.user_query, embedding: $vec, toolsCalled: $t.tools_called, turnCount: $t.turn_count,
                 successScore: null, confidence: $t.confidence, resolutionPath: $t.resolution_path,
                 discovery: $t.discovery, createdAt: datetime(), reviewedBy: null})
         CREATE (e)-[:GENERATED_BY]->(ag)
         WITH e CALL (e) { UNWIND apoc.coll.toSet($t.tools_called) AS x MATCH (n:Tool {name: x}) MERGE (e)-[:USED]->(n) }
         CALL (e) { UNWIND $t.tables AS name MATCH (x:Table)<-[:INCLUDES]-(d:DataProduct)
                    WHERE toUpper(x.fq_name) = toUpper(name) WITH DISTINCT d MERGE (e)-[:ACCESSED]->(d) }
         CALL (e) { UNWIND apoc.coll.toSet($t.tools_called) AS x MATCH (:Tool {name: x})-[:EXPOSES]->(d:DataProduct)
                    WITH DISTINCT d MERGE (e)-[:ACCESSED]->(d) }
         CALL (e) { UNWIND range(0, size($followed) - 1) AS i MATCH (k:BusinessTask {id: $followed[i]})
                    MERGE (e)-[:FOLLOWED {order: i + 1}]->(k) }
         CALL (e) { UNWIND $t.policy_checks AS c MATCH (p:Policy {id: c.policy}) MERGE (e)-[r:CHECKED]->(p)
                    SET r.decision = c.decision }
         CALL (e) { UNWIND $t.entities AS x MATCH (n) WHERE (n:Supplier OR n:Material) AND n.id = x MERGE (e)-[:ABOUT]->(n) }
         CALL (e) { UNWIND $t.reused_assets AS x MATCH (k:KnowledgeAsset {id: x}) MERGE (e)-[:REUSES]->(k) }
         RETURN e.id AS id
